/* Local, offline worker. No network calls or DOM access. */
importScripts('engine.js','intelligence.js');
self.onmessage=event=>{const {id,type,data,args=[]}=event.data;try{let result;if(type==='optimize')result=DAIntelligence.optimize(data,args[0],args[1],progress=>self.postMessage({id,progress}));else if(type==='evaluate')result=DAIntelligence.context(data).evaluate(args[0]);else if(type==='attribution')result=DAIntelligence.attribution(data,args[0]);else if(type==='isochrone')result=DAIntelligence.isochrone(data,...args);else if(type==='fragility')result=DAIntelligence.fragility(data,args[0]);else if(type==='import'){if(!self.DAImporter)importScripts('vendor/turf.min.js','importer.js');result=DAImporter.convert(data,...args);}else throw new Error('Unknown worker request');self.postMessage({id,result});}catch(error){self.postMessage({id,error:error.message});}};
